Here is the commit message:
sctp: fix ignoring asoc_id for tcp-style sockets on
 SCTP_ENABLE_STREAM_RESET sockopt

A similar fix as Patch "sctp: fix ignoring asoc_id for tcp-style sockets on
SCTP_DEFAULT_SEND_PARAM sockopt" on SCTP_ENABLE_STREAM_RESET sockopt.

Fixes: 99a62135e127 ("sctp: use SCTP_FUTURE_ASSOC and add SCTP_CURRENT_ASSOC for SCTP_ENABLE_STREAM_RESET sockopt")
Signed-off-by: Xin Long <lucien.xin@gmail.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug arises from the incorrect handling of the association ID (`assoc_id`) for TCP-style sockets when setting the `SCTP_ENABLE_STREAM_RESET` socket option. Specifically, the code was not properly assigning the `assoc_id` to `SCTP_FUTURE_ASSOC` for TCP-style sockets, leading to potential misconfigurations and unexpected behavior when enabling stream resets.

Here is the patch:

 static int sctp_setsockopt_enable_strreset(struct sock *sk,
 					   char __user *optval,
 					   unsigned int optlen)
 {
 	struct sctp_endpoint *ep = sctp_sk(sk)->ep;
 	struct sctp_assoc_value params;
 	struct sctp_association *asoc;
 	int retval = -EINVAL;

 	if (optlen != sizeof(params))
 		goto out;

 	if (copy_from_user(&params, optval, optlen)) {
 		retval = -EFAULT;
 		goto out;
 	}

 	if (params.assoc_value & (~SCTP_ENABLE_STRRESET_MASK))
 		goto out;

 	asoc = sctp_id2assoc(sk, params.assoc_id);
 	if (!asoc && params.assoc_id > SCTP_ALL_ASSOC &&
 	    sctp_style(sk, UDP))
 		goto out;

 	retval = 0;

 	if (asoc) {
 		asoc->strreset_enable = params.assoc_value;
 		goto out;
 	}

+	if (sctp_style(sk, TCP))
+		params.assoc_id = SCTP_FUTURE_ASSOC;
+
 	if (params.assoc_id == SCTP_FUTURE_ASSOC ||
 	    params.assoc_id == SCTP_ALL_ASSOC)
 		ep->strreset_enable = params.assoc_value;

 	if (params.assoc_id == SCTP_CURRENT_ASSOC ||
 	    params.assoc_id == SCTP_ALL_ASSOC)
 		list_for_each_entry(asoc, &ep->asocs, asocs)
 			asoc->strreset_enable = params.assoc_value;

 out:
 	return retval;
 }



